 const unsafe=!surface||!Number.isFinite(target)||surface.normalY<.97||/树|湖面/.test(surface.label)||target>state.altitude+.01;
 const blocked=!unsafe&&window.worldCollision?.({x:p.x,y:p.y,z:state.altitude},{x:p.x,y:p.y,z:target});
 if(unsafe||blocked){state.status='paused';state.targetAltitude=state.altitude;mission.title='已到达点位，下方暂不适合降落';mission.summary='下方没有可用的平整表面，或垂直下降通道受到遮挡。无人机保持悬停，请手动调整位置后重新规划。';log('landing_blocked','降落通道检查未通过',surface?.label||'无地表');render();return false}
