 const name=state.goalDeferred?'起降区':mission.destination.name;mission.title='已到达'+name+'，自动下降着陆';mission.summary='无人机保持水平位置，正在下降；接近地面时自动减速，着陆后结束本次任务。可使用暂停或悬停中断下降。';log('landing_start','到点自动降落',JSON.stringify(state.landing));render();return true;
